        where table_schema = 'public' and (column_name like '%\\_sen' or column_name in
          ('start_date','end_date','period_start','period_end','due_date','received_at','paid_at','created_at','decided_at','updated_at'))
        order by 1, 2`,
    );
    for (const r of rows) {
